import json
import os
import sys
import threading
import time
import traceback
import uuid

LOG = "/tmp/cmux-agent-badges/agent.log"


def log(text):
    try:
        with open(LOG, "a") as out:
            out.write(time.strftime("%H:%M:%S ") + text + "\n")
    except OSError:
        pass


FINDER = """import json, sys


def walk(v):
    if isinstance(v, dict):
        for k in ("request_id", "requestId"):
            if isinstance(v.get(k), (str, int)):
                print(v[k])
                sys.exit(0)
        for x in v.values():
            walk(x)
    elif isinstance(v, list):
        for x in v:
            walk(x)


walk(json.load(sys.stdin))
"""

LOCK = threading.Lock()


def send(message):
    with LOCK:
        sys.stdout.write(json.dumps(message) + "\n")
        sys.stdout.flush()
    log("out " + json.dumps(message)[:160])


def say(sid, text):
    send({"jsonrpc": "2.0", "method": "session/update", "params": {"sessionId": sid, "update": {
        "sessionUpdate": "agent_message_chunk", "content": {"type": "text", "text": text}}}})


def prompt_text(params):
    return "".join(b.get("text", "") for b in params.get("prompt", []) if isinstance(b, dict)).strip()


def wait_for(path, limit=90):
    """The gate: an ordinary file appears (never a FIFO a writer blocks on)."""
    end = time.time() + limit
    while time.time() < end and not os.path.exists(path):
        time.sleep(0.2)
    log(f"gate {path} {'open' if os.path.exists(path) else 'timed out'}")


DIR = os.path.dirname(LOG)
pending = {}
answers = {}
turns = {}
asks = 0


def end(rid, reason):
    """Ends turn `rid` once; a later end (a cancel after the gate) is a no-op."""
    if turns.pop(rid, None) is not None:
        send({"jsonrpc": "2.0", "id": rid, "result": {"stopReason": reason}})


def release(rid, sid):
    """One turn the tour drives by files in DIR: go -> it asks to deploy; done (or an answer) -> it reports back."""
    global asks
    wait_for(os.path.join(DIR, "go"))
    if rid not in turns:
        return
    asks += 1
    ask_id = f"ask-{asks}"
    pending[ask_id] = (rid, sid)
    send({"jsonrpc": "2.0", "id": ask_id, "method": "session/request_permission", "params": {
        "sessionId": sid,
        "toolCall": {"toolCallId": f"call-{asks}", "title": "Deploy release to staging", "kind": "execute",
                     "status": "pending"},
        "options": [{"optionId": "allow", "name": "Allow", "kind": "allow_once"},
                    {"optionId": "reject", "name": "Reject", "kind": "reject_once"}]}})
    done = os.path.join(DIR, "done")
    limit = time.time() + 90
    while ask_id in pending and time.time() < limit and not os.path.exists(done):
        time.sleep(0.2)
    log(f"ask {ask_id} {'answered' if ask_id not in pending else 'done file'}")
    pending.pop(ask_id, None)
    if rid in turns:
        send({"jsonrpc": "2.0", "method": "session/update", "params": {"sessionId": sid, "update": {
            "sessionUpdate": "tool_call_update", "toolCallId": f"call-{asks}", "status": "completed"}}})
        if answers.get(ask_id) == "reject":
            say(sid, " Deploy held. The release checks passed.")
        else:
            say(sid, " Deployed to staging. Every check passed.")
        end(rid, "end_turn")


def handle(msg):
    method, rid = msg.get("method"), msg.get("id")
    if method is None and rid in pending:
        pending.pop(rid)
        answers[rid] = ((msg.get("result") or {}).get("outcome") or {}).get("optionId")
        log(f"answer {json.dumps(msg.get('result'))[:120]}")
        return
    if method == "session/cancel":
        pending.clear()
        for prompt_id in list(turns):
            end(prompt_id, "cancelled")
        return
    if rid is None:
        return
    if method == "initialize":
        send({"jsonrpc": "2.0", "id": rid, "result": {
            "protocolVersion": 1,
            "agentInfo": {"name": "badges-agent", "title": "Release agent", "version": "1.0.0"},
            "agentCapabilities": {"loadSession": False, "promptCapabilities": {}}}})
    elif method == "session/new":
        send({"jsonrpc": "2.0", "id": rid, "result": {"sessionId": str(uuid.uuid4())}})
    elif method == "session/prompt":
        params = msg.get("params", {})
        sid, text = params.get("sessionId"), prompt_text(params)
        log("prompt " + json.dumps(text)[:200])
        turns[rid] = sid
        if "release" in text.lower():
            say(sid, "Running the release checks.")
            # Beside the stdin loop, so the agent keeps answering (a cancel, a permission reply).
            threading.Thread(target=release, args=(rid, sid), daemon=True).start()
        else:
            say(sid, text)
            end(rid, "end_turn")
    else:
        send({"jsonrpc": "2.0", "id": rid, "result": {}})


os.makedirs(os.path.dirname(LOG), exist_ok=True)
# The tour answers the ask from a shell: this prints the first request id `cmux agents dialog list` names.
with open(os.path.join(DIR, "request_id.py"), "w") as out:
    out.write(FINDER)
log(f"start pid {os.getpid()} {sys.executable} {sys.version.split()[0]} cwd {os.getcwd()}")
for line in sys.stdin:
    try:
        msg = json.loads(line)
    except ValueError:
        continue
    log("in  " + line.strip()[:160])
    try:
        handle(msg)
    except Exception:
        log("error " + traceback.format_exc().replace("\n", " | "))
log("stdin closed")
